import { type NextRequest, NextResponse } from 'next/server'
import { getConnectionFromHeaders } from '@/lib/api-auth'
import { DEMO_CONNECTION_ID } from '@/lib/demo-data'
import { projectRefFromUrl, SupabaseMcpClient } from '@/lib/supabase-mcp-client'
import type { LogEntry, LogService, LogsQueryResult } from '@/lib/supabase-types'

interface LogsRequestBody {
  service?: LogService
  startTime?: string
  endTime?: string
  filter?: string
  /** Correlated mode: filter api + edge-function logs for this W3C trace id (32 hex). */
  traceId?: string
  limit?: number
}

const DEFAULT_LIMIT = 500

const SEVERITY_VALUES = new Set(['ERROR', 'WARN', 'INFO', 'DEBUG', 'UNKNOWN'])

// Map user-facing service values to the MCP get_logs service enum.
const SERVICE_TO_MCP: Record<LogService, string> = {
  postgres: 'postgres',
  api: 'api',
  auth: 'auth',
  'edge-functions': 'edge-function',
  storage: 'storage',
  realtime: 'realtime',
}

function detectSeverity(raw: Record<string, unknown>): LogEntry['severity'] {
  const fromField =
    raw.error_severity ??
    raw.level ??
    raw.severity ??
    (raw.metadata && typeof raw.metadata === 'object'
      ? (raw.metadata as Record<string, unknown>).error_severity ??
        (raw.metadata as Record<string, unknown>).level ??
        (raw.metadata as Record<string, unknown>).severity
      : undefined)

  if (typeof fromField === 'string') {
    const upper = fromField.toUpperCase()
    if (SEVERITY_VALUES.has(upper)) return upper as LogEntry['severity']
    if (upper === 'WARNING') return 'WARN'
    if (upper === 'FATAL' || upper === 'CRITICAL' || upper === 'PANIC') return 'ERROR'
  }

  const text = JSON.stringify(raw).toLowerCase()
  if (text.includes('fatal') || text.includes('panic') || text.includes('error') || text.includes('failed')) {
    return 'ERROR'
  }
  if (text.includes('warn')) return 'WARN'
  if (text.includes('debug')) return 'DEBUG'
  if (text.includes('info')) return 'INFO'
  return 'UNKNOWN'
}

function normalizeLogEntry(raw: unknown, service: LogService): LogEntry | null {
  if (!raw || typeof raw !== 'object') return null
  const r = raw as Record<string, unknown>

  const id = String(
    r.id ?? r.log_id ?? r.request_id ?? r.query_id ?? r.span_id ?? `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
  )

  const timestamp = String(
    r.timestamp ?? r.timestamp_end ?? r.time ?? r.timestamp_start ?? new Date().toISOString()
  )

  const message = String(
    r.event_message ?? r.message ?? r.error ?? r.msg ?? r.content ?? r.text ?? JSON.stringify(r)
  )

  const metadata =
    r.metadata && typeof r.metadata === 'object'
      ? (r.metadata as Record<string, unknown>)
      : Object.fromEntries(Object.entries(r).filter(([k]) => k !== 'event_message' && k !== 'message'))

  return {
    id,
    timestamp,
    service,
    severity: detectSeverity(r),
    message,
    metadata,
    raw: r,
  }
}

function parseMcpLogsOutput(text: string, service: LogService): LogEntry[] {
  if (!text?.trim()) return []
  const trimmed = text.trim()

  // Try JSON first — the MCP may return an array or object.
  if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
    try {
      const parsed = JSON.parse(trimmed)
      const rows = Array.isArray(parsed) ? parsed : (parsed as Record<string, unknown>).result ?? (parsed as Record<string, unknown>).logs ?? []
      return (rows as unknown[])
        .map((entry) => normalizeLogEntry(entry, service))
        .filter((entry): entry is LogEntry => entry !== null)
    } catch {
      // Fall through to line parsing
    }
  }

  // Fallback: treat each non-empty line as a log entry.
  const now = new Date().toISOString()
  return trimmed
    .split('\n')
    .filter((line) => line.trim())
    .map((line, i) => ({
      id: `${Date.now()}-${i}`,
      timestamp: now,
      service,
      severity: detectSeverity({ event_message: line }) as LogEntry['severity'],
      message: line,
      metadata: {},
      raw: { event_message: line },
    }))
}

// Route modules may only export HTTP handlers — keep this local (no other callers).
async function fetchLogsWithCreds(
  accessToken: string,
  projectRef: string,
  service: LogService,
  limit: number,
  traceId?: string
): Promise<NextResponse> {
  // Correlated mode: pull the two services that carry the propagated trace id
  // (API gateway + edge functions) and filter full-raw-JSON for it — field-name
  // agnostic, no dependency on MCP get_logs query parameters.
  const services: LogService[] = traceId ? ['api', 'edge-functions'] : [service]

  try {
    const results = await Promise.all(
      services.map(async (svc) => {
        const client = new SupabaseMcpClient({ projectRef, accessToken })
        try {
          // No project_id — the client scopes the session with ?project_ref=, and the
          // hosted server now rejects the key outright ("Unrecognized key: project_id").
          const resultText = await client.callTool('get_logs', {
            service: SERVICE_TO_MCP[svc],
          })
          return parseMcpLogsOutput(resultText, svc)
        } finally {
          client.disconnect().catch(() => {})
        }
      })
    )

    let logs = results.flat()
    if (traceId) {
      logs = logs.filter((entry) => JSON.stringify(entry.raw).includes(traceId))
    }
    logs = logs
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
      .slice(0, limit)

    return NextResponse.json({ logs } satisfies LogsQueryResult)
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'MCP get_logs failed'
    const sanitized = msg.replace(/eyJ[A-Za-z0-9._-]{20,}/g, '[token]')
    const isAuthError = /unauthorized|jwt|token.*(expired|invalid)|permission/i.test(msg)
    return NextResponse.json(
      { logs: [], error: sanitized } satisfies LogsQueryResult,
      { status: isAuthError ? 401 : 502 }
    )
  }
}

// POST /api/logs
// body: { service, startTime, endTime, filter?, limit? }
export async function POST(request: NextRequest) {
  try {
    const connection = getConnectionFromHeaders(request)
    if (!connection) {
      return NextResponse.json({ logs: [], error: 'No connection provided' } satisfies LogsQueryResult, { status: 400 })
    }

    if (connection.id === DEMO_CONNECTION_ID) {
      return NextResponse.json({ logs: [] } satisfies LogsQueryResult)
    }

    const accessToken = connection.accessToken
    if (!accessToken) {
      return NextResponse.json(
        { logs: [], error: 'Management API access token required to fetch logs. Connect via OAuth.' } satisfies LogsQueryResult,
        { status: 403 }
      )
    }

    const projectRef = projectRefFromUrl(connection.supabaseUrl)
    if (!projectRef) {
      return NextResponse.json(
        { logs: [], error: 'Could not extract project ref from Supabase URL.' } satisfies LogsQueryResult,
        { status: 400 }
      )
    }

    const body = (await request.json().catch(() => ({}))) as LogsRequestBody
    const service: LogService = body.service ?? 'postgres'
    const limit = Math.min(Math.max(Number(body.limit ?? DEFAULT_LIMIT), 1), 1000)

    return fetchLogsWithCreds(accessToken, projectRef, service, limit, body.traceId)
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    const status = /unauthorized|jwt|token|auth/i.test(msg) ? 401 : 500
    return NextResponse.json({ logs: [], error: `Failed to fetch logs: ${msg}` } satisfies LogsQueryResult, { status })
  }
}

