  if (!conn.refreshToken) return null
  try {
    const clientId = client?.clientId ?? sessionStorage.getItem('supabase_dcr_client_id')
    const clientSecret = client?.clientSecret ?? sessionStorage.getItem('supabase_dcr_client_secret')
    if (!clientId) return null""",1)

