  --font-sans: "Custom Font", "Circular", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-mono: "Source Code Pro", "Office Code Pro", "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* ── Supabase DS HSL color tokens (light / default) ── */
  --colors-gray-light-100: 0deg 0% 98.8%;
