  --colors-gray-light-700: 0deg 0% 85.9%;
  --colors-gray-light-800: 0deg 0% 78%;
  --colors-gray-light-900: 0deg 0% 56.1%;
  --colors-gray-light-1000: 0deg 0% 52.2%;
  --colors-gray-light-1100: 0deg 0% 43.5%;
  --colors-gray-light-1200: 0deg 0% 9%;

  /* Supabase DS semantic tokens — light */
  --background-default: 0deg 0% 98.8%;
  --background-200: 0deg 0% 97.3%;
  --background-surface-75: 0deg 0% 100%;
  --background-surface-100: 0deg 0% 98.8%;
  --background-surface-200: 0deg 0% 95.3%;
  --background-surface-300: 0deg 0% 92.9%;
  --background-surface-400: 0deg 0% 89.8%;
  --background-control: 0deg 0% 95.3%;
  --background-overlay-default: 0deg 0% 98.8%;
  --background-overlay-hover: 0deg 0% 95.3%;
  --background-selection: 0deg 0% 92.9%;
  --background-muted: 0deg 0% 96.9%;
  --background-alternative-default: 0deg 0% 99.2%;
  --background-dash-canvas: 0deg 0% 97.3%;
  --background-dash-sidebar: 0deg 0% 98.8%;
  --background-button-default: 0deg 0% 98.8%;

  --foreground-default: 0deg 0% 9%;
  --foreground-light: 0deg 0% 32.2%;
  --foreground-lighter: 0deg 0% 43.9%;
  --foreground-muted: 0deg 0% 69.8%;
  --foreground-contrast: 0deg 0% 98.4%;

  --border-default: 0deg 0% 87.5%;
  --border-strong: 0deg 0% 83.1%;
  --border-stronger: 0deg 0% 56.1%;
  --border-muted: 0deg 0% 92.9%;
  --border-alternative: 0deg 0% 91%;
  --border-overlay: 0deg 0% 91%;
  --border-control: 0deg 0% 78%;
  --border-button-default: 0deg 0% 88.6%;
  --border-button-hover: 0deg 0% 85.9%;

  --brand-default: 152.9deg 60% 52.9%;
  --brand-link: 153.4deg 100% 36.7%;
  --brand-600: 156.5deg 86.5% 26.1%;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 14px;
  --r-xl: 20px;

  /* shadcn mapping — Supabase DS light palette */
  --background: oklch(0.988 0 0); /* DS background-default 98.8% */
  --foreground: oklch(0.15 0 0);  /* DS foreground-default 9% */
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.15 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.15 0 0);
  --primary: var(--brand-supabase);
  --primary-foreground: oklch(0.13 0.04 159);
  --secondary: oklch(0.953 0 0); /* DS surface-200 95.3% */
  --secondary-foreground: oklch(0.15 0 0);
  --muted: oklch(0.953 0 0);
  --muted-foreground: oklch(0.56 0 0); /* DS foreground-lighter 43.9% */
  --accent: oklch(0.953 0 0);
  --accent-foreground: oklch(0.15 0 0);
  --destructive: oklch(0.55 0.205 25);
  --border: oklch(0 0 0 / 13%);   /* DS border-default 87.5% lightness ≈ 12.5% opacity black */
  --input: oklch(0 0 0 / 8%);
  --ring: var(--brand-supabase);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.988 0 0);    /* DS dash-sidebar 98.8% */
  --sidebar-foreground: oklch(0.15 0 0);
  --sidebar-primary: var(--brand-supabase);
  --sidebar-primary-foreground: oklch(0.13 0.04 159);
  --sidebar-accent: oklch(0.953 0 0);
  --sidebar-accent-foreground: oklch(0.15 0 0);
  --sidebar-border: oklch(0 0 0 / 13%);
  --sidebar-ring: var(--brand-supabase);

  /* Agentic Labs semantic tokens */
  --agl-bg: oklch(0.955 0 0);
  --agl-surface: oklch(1 0 0);
  --agl-surface-2: oklch(0.936 0 0);
  --agl-overlay: oklch(1 0 0 / 0.92);
  --agl-fg: oklch(0.145 0 0);
  --agl-fg-muted: oklch(0.445 0 0);
  --agl-fg-subtle: oklch(0.556 0 0);
  --agl-fg-faint: oklch(0.68 0 0);
  --agl-fg-inverse: #ffffff;
  --agl-accent: var(--brand-supabase);
  --agl-accent-hover: oklch(0.66 0.164 159);
  --agl-accent-soft: color-mix(in oklch, var(--brand-supabase) 14%, transparent);
  --agl-accent-soft-hover: color-mix(in oklch, var(--brand-supabase) 22%, transparent);
  --agl-on-accent: #ffffff;
  --agl-border: oklch(0 0 0 / 12%);
  --agl-border-subtle: oklch(0 0 0 / 6%);
  --agl-border-strong: oklch(0 0 0 / 22%);
  --agl-success: oklch(55% 0.135 160);
  --agl-success-muted: oklch(94% 0.045 160);
  --agl-warning: oklch(55% 0.145 65);
  --agl-warning-muted: oklch(94% 0.045 65);
  --agl-error: oklch(55% 0.205 25);
  --agl-error-muted: oklch(94% 0.045 25);
  --agl-pending: oklch(55% 0.18 295);
  --agl-pending-muted: oklch(94% 0.045 295);
}

