/** Compact a function signature to fit the rail: "text, text[]" or "text → jsonb". */
function signature(fn: DbFunction): string {
  const args = (fn.arguments || '').replace(/\s+DEFAULT\s+[^,]+/gi, '').trim()
  const ret = fn.return_type?.trim()
  if (args && ret) return args.length > 14 ? args : `${args} → ${ret}`
  return args || ret || ''
}

